SELECT
  m._id, m.date_sent, m.date_received, m.date_server, m.type, m.thread_id, t.recipient_id AS thread_recipient,
  m.from_recipient_id, m.to_recipient_id, m.view_once, m.deleted_by,
  (SELECT count(*) FROM attachment a WHERE a.message_id = m._id) AS n_attachments,
  CASE WHEN length(m.body) > 0 THEN 1 ELSE 0 END AS has_body
FROM message m
LEFT JOIN thread t ON t._id = m.thread_id
WHERE m.date_sent BETWEEN {{unixMsStart}} AND {{unixMsEnd}}
   OR m.date_received BETWEEN {{unixMsStart}} AND {{unixMsEnd}}
ORDER BY m.date_received;
